#!/usr/bin/env python3
"""Package reviewed solution source as data; never execute notebook cells or source."""
import argparse,hashlib,io,json,zipfile
from pathlib import Path
from soup_queue import validate_artifact

def bundle(source):
 source=Path(source).absolute()
 if source.is_symlink() or not source.is_dir():raise ValueError('Real solution directory required')
 out=io.BytesIO();files={}
 with zipfile.ZipFile(out,'w',compression=zipfile.ZIP_DEFLATED) as z:
  for p in sorted(source.rglob('*')):
   if p.is_symlink():raise ValueError('Symlinks rejected')
   # Interpreter-generated bytecode is never source and never enters a review packet.
   if '__pycache__' in p.relative_to(source).parts or p.suffix in ('.pyc','.pyo'):continue
   if p.is_dir():continue
   name='solution/'+p.relative_to(source).as_posix();raw=p.read_bytes();files[name]=hashlib.sha256(raw).hexdigest();entry=zipfile.ZipInfo(name,(2026,1,1,0,0,0));entry.external_attr=0o100644<<16;entry.compress_type=zipfile.ZIP_DEFLATED;z.writestr(entry,raw)
 raw=out.getvalue();validate_artifact(raw,'solution_bundle');return raw,files
if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--solution-dir',required=True);p.add_argument('--out',required=True);p.add_argument('--manifest',required=True);a=p.parse_args();raw,files=bundle(a.solution_dir)
 if Path(a.out).exists() or Path(a.manifest).exists():raise SystemExit('Output exists; no overwrite')
 with Path(a.out).open('xb') as f:f.write(raw)
 with Path(a.manifest).open('x') as f:json.dump(files,f,indent=2);f.write('\n')
 print(json.dumps({'source_sha256':hashlib.sha256(raw).hexdigest(),'files':files,'review_required':True},indent=2))
